import { ChevronLeft, ChevronRight } from 'lucide-react';
import { Button } from '@/components/ui/button';
import {
  Pagination as PaginationNav,
  PaginationContent,
  PaginationItem,
  PaginationLink,
} from '@/components/ui/pagination';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';

interface PaginationProps {
  page: number;
  pageSize: number;
  total: number;
  onPageChange: (page: number) => void;
  pageSizeOptions?: readonly number[];
  onPageSizeChange?: (pageSize: number) => void;
  /** 摘要文案（缺省「共 N 条」） */
  summaryLabel?: (total: number) => string;
}

function pageWindow(current: number, totalPages: number): number[] {
  const windowSize = 5;
  const start = Math.max(1, Math.min(current - Math.floor(windowSize / 2), totalPages - windowSize + 1));
  return Array.from({ length: Math.min(windowSize, Math.max(totalPages, 1)) }, (_, index) => start + index).filter(
    (value) => value >= 1 && value <= totalPages,
  );
}

/** 远程分页条：页码窗 + 可选每页条数（页码/条数由调用方写入 URL） */
export function Pagination({
  page,
  pageSize,
  total,
  onPageChange,
  pageSizeOptions,
  onPageSizeChange,
  summaryLabel,
}: PaginationProps) {
  const totalPages = Math.max(1, Math.ceil(total / Math.max(pageSize, 1)));
  const current = Math.min(page, totalPages);
  return (
    <div className="flex flex-wrap items-center justify-between gap-3 pt-3 text-sm text-muted-foreground">
      <span>
        {summaryLabel ? summaryLabel(total) : `共 ${total} 条`} · 第 {current} / {totalPages} 页
      </span>
      <PaginationNav className="mx-0 w-auto">
        <PaginationContent className="gap-2">
          {pageSizeOptions && onPageSizeChange ? (
            <PaginationItem>
              <span className="flex items-center gap-2">
                <span>每页</span>
                <Select
                  value={String(pageSize)}
                  onValueChange={(value) => {
                    if (value != null) {
                      onPageSizeChange(Number(value));
                    }
                  }}
                  items={pageSizeOptions.map((option) => ({ value: String(option), label: String(option) }))}
                >
                  <SelectTrigger className="h-8 w-[4.5rem]" aria-label="每页条数">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    {pageSizeOptions.map((option) => (
                      <SelectItem key={option} value={String(option)}>
                        {option}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
                <span>条</span>
              </span>
            </PaginationItem>
          ) : null}
          <PaginationItem>
            <Button
              variant="outline"
              size="icon"
              className="h-8 w-8"
              aria-label="上一页"
              disabled={current <= 1}
              onClick={() => onPageChange(current - 1)}
            >
              <ChevronLeft />
            </Button>
          </PaginationItem>
          {pageWindow(current, totalPages).map((value) => (
            <PaginationItem key={value}>
              <PaginationLink
                href="#"
                aria-label={`第 ${value} 页`}
                isActive={value === current}
                className="h-8 w-8"
                onClick={(event) => event.preventDefault()}
              >
                {value}
              </PaginationLink>
            </PaginationItem>
          ))}
          <PaginationItem>
            <Button
              variant="outline"
              size="icon"
              className="h-8 w-8"
              aria-label="下一页"
              disabled={current >= totalPages}
              onClick={() => onPageChange(current + 1)}
            >
              <ChevronRight />
            </Button>
          </PaginationItem>
        </PaginationContent>
      </PaginationNav>
    </div>
  );
}
